// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.memory;

import java.util.Random;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.repository.RepositoryConnection;

/**
 * Generates a synthetic "group with an optional typed link" dataset shaped like the {@code FILTER NOT EXISTS} query in
 * {@link FilterNotExistsJoinOrderExplainTest}, so that {@code explain(Explanation.Level.Optimized)} can be inspected
 * against realistic cardinalities and selectivity rather than a handful of hand-written triples.
 * <p>
 * The data is split across two named graphs to mirror the {@code FROM <DataContext> FROM <InferenceContext>} dataset of
 * the query: asserted facts (types, labels, link-to-group links) go into the data graph, while the {@code rdf:type}
 * triples of the links go into the inference graph, as if they had been materialized by a reasoner.
 */
final class FilterNotExistsJoinOrderDataGenerator {

	static final String MODEL_NAMESPACE = "http://example.org/ns/model/";
	static final String DATA_GRAPH = "http://example.org/ns/graph/DataContext";
	static final String INFERENCE_GRAPH = "http://example.org/ns/graph/InferenceContext";

	private static final String GROUP_NAMESPACE = "http://example.org/ns/group/";
	private static final String LINK_NAMESPACE = "http://example.org/ns/link/";
	private static final String ITEM_NAMESPACE = "http://example.org/ns/item/";

	private final ValueFactory vf = SimpleValueFactory.getInstance();

	private final IRI groupType = vf.createIRI(MODEL_NAMESPACE, "Group");
	private final IRI itemType = vf.createIRI(MODEL_NAMESPACE, "Item");
	private final IRI linkType = vf.createIRI(MODEL_NAMESPACE, "Link");
	private final IRI otherLinkType = vf.createIRI(MODEL_NAMESPACE, "OtherLink");
	private final IRI label = vf.createIRI(MODEL_NAMESPACE, "label");
	private final IRI memberOf = vf.createIRI(MODEL_NAMESPACE, "memberOf");

	private final IRI dataGraph = vf.createIRI(DATA_GRAPH);
	private final IRI inferenceGraph = vf.createIRI(INFERENCE_GRAPH);

	/**
	 * Counts describing one call to {@link #generate}.
	 */
	static final class Summary {

		/** Total {@code ?g a Group} entities generated. */
		final int groups;
		/** How many of those have at least one {@code Link}, i.e. are filtered out by the query. */
		final int groupsWithLink;
		/**
		 * How many groups only carry links of some other type, so the query's {@code NOT EXISTS} has to check the link
		 * type rather than merely its existence.
		 */
		final int groupsWithOnlyOtherLink;
		/** Total {@code Link} instances generated. */
		final int links;
		/** Total link instances of any other type generated. */
		final int otherLinks;
		/** Background {@code Item} entities that also carry a label but are not groups. */
		final int noiseItems;

		Summary(int groups, int groupsWithLink, int groupsWithOnlyOtherLink,
				int links, int otherLinks, int noiseItems) {
			this.groups = groups;
			this.groupsWithLink = groupsWithLink;
			this.groupsWithOnlyOtherLink = groupsWithOnlyOtherLink;
			this.links = links;
			this.otherLinks = otherLinks;
			this.noiseItems = noiseItems;
		}

		/** How many groups the query is expected to return. */
		int expectedResults() {
			return groups - groupsWithLink;
		}

		@Override
		public String toString() {
			return "Summary{groups=" + groups + ", groupsWithLink="
					+ groupsWithLink + ", groupsWithOnlyOtherLink="
					+ groupsWithOnlyOtherLink + ", links=" + links
					+ ", otherLinks=" + otherLinks + ", noiseItems=" + noiseItems
					+ ", expectedResults=" + expectedResults() + '}';
		}
	}

	/**
	 * Loads {@code groupCount} groups, each with a label literal, plus links pointing back at them and unrelated
	 * background entities.
	 * <p>
	 * Roughly {@code associatedFraction} of the groups (chosen deterministically from {@code seed}) receive between
	 * {@code minLinks} and {@code maxLinks} inclusive links. Each of those links is a {@code Link} with probability
	 * {@code linkFraction} and some other link type otherwise, so the query's {@code NOT EXISTS} sees groups with a
	 * matching link, groups whose only links are of the wrong type, and groups with no links at all.
	 *
	 * @param connection         an open connection to load the data into; this method manages its own transaction
	 * @param groupCount         number of {@code Group} entities to generate
	 * @param associatedFraction fraction of groups that receive any link at all, e.g. 0.60
	 * @param linkFraction       fraction of the generated links that are typed {@code Link}, e.g. 0.70
	 * @param minLinks           minimum number of links per associated group, inclusive
	 * @param maxLinks           maximum number of links per associated group, inclusive
	 * @param noiseItemCount     number of background {@code Item} entities, which carry a label but are not groups
	 * @param seed               seed for the deterministic {@link Random} driving the choices above
	 */
	Summary generate(RepositoryConnection connection, int groupCount, double associatedFraction,
			double linkFraction, int minLinks, int maxLinks, int noiseItemCount,
			long seed) {
		if (minLinks < 1 || maxLinks < minLinks) {
			throw new IllegalArgumentException("expected 1 <= minLinks <= maxLinks");
		}
		Random random = new Random(seed);

		int groupsWithLink = 0;
		int groupsWithOnlyOtherLink = 0;
		int links = 0;
		int otherLinks = 0;

		connection.begin();
		try {
			for (int g = 0; g < groupCount; g++) {
				IRI group = vf.createIRI(GROUP_NAMESPACE + "group" + g);
				connection.add(group, RDF.TYPE, groupType, dataGraph);
				connection.add(group, label, vf.createLiteral("label-" + g), dataGraph);

				if (random.nextDouble() >= associatedFraction) {
					continue;
				}
				int linkCount = minLinks + random.nextInt(maxLinks - minLinks + 1);
				boolean sawLink = false;
				for (int a = 0; a < linkCount; a++) {
					IRI link = vf.createIRI(LINK_NAMESPACE + "assoc" + g + "-" + a);
					connection.add(link, memberOf, group, dataGraph);
					if (random.nextDouble() < linkFraction) {
						connection.add(link, RDF.TYPE, linkType, inferenceGraph);
						links++;
						sawLink = true;
					} else {
						connection.add(link, RDF.TYPE, otherLinkType, inferenceGraph);
						otherLinks++;
					}
				}
				if (sawLink) {
					groupsWithLink++;
				} else {
					groupsWithOnlyOtherLink++;
				}
			}

			for (int n = 0; n < noiseItemCount; n++) {
				IRI item = vf.createIRI(ITEM_NAMESPACE + "item" + n);
				connection.add(item, RDF.TYPE, itemType, dataGraph);
				connection.add(item, label, vf.createLiteral("label-item-" + n), dataGraph);
			}

			connection.commit();
		} catch (RuntimeException e) {
			connection.rollback();
			throw e;
		}

		return new Summary(groupCount, groupsWithLink, groupsWithOnlyOtherLink,
				links, otherLinks, noiseItemCount);
	}
}
